ALTER TABLE public.bot_groups ADD COLUMN coordinator_id uuid REFERENCES public.bots(id) ON DELETE CASCADE, ADD COLUMN category text NOT NULL DEFAULT 'Unassigned';
CREATE OR REPLACE FUNCTION public.save_bot_group(p_name text, p_coordinator uuid, p_members uuid[], p_category text DEFAULT 'Unassigned', p_id uuid DEFAULT NULL) RETURNS public.bot_groups LANGUAGE plpgsql SET search_path = public AS $$ DECLARE g public.bot_groups; n integer; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF length(trim(p_name)) < 2 OR length(trim(p_name)) > 60 THEN RAISE EXCEPTION 'Invalid group name'; END IF; SELECT count(DISTINCT x) INTO n FROM unnest(p_members) x; IF n < 2 OR n > 8 OR n <> cardinality(p_members) THEN RAISE EXCEPTION 'Choose 2 to 8 distinct bots'; END IF; IF NOT EXISTS (SELECT 1 FROM bots WHERE id=p_coordinator AND owner_id=auth.uid()) OR (SELECT count(*) FROM bots WHERE id=ANY(p_members) AND owner_id=auth.uid()) <> n THEN RAISE EXCEPTION 'Bots must belong to you'; END IF; IF p_id IS NULL THEN INSERT INTO bot_groups(owner_id,name,coordinator_id,category) VALUES(auth.uid(),trim(p_name),p_coordinator,left(p_category,60)) RETURNING * INTO g; ELSE UPDATE bot_groups SET name=trim(p_name),coordinator_id=p_coordinator,category=left(p_category,60) WHERE id=p_id AND owner_id=auth.uid() RETURNING * INTO g; IF g.id IS NULL THEN RAISE EXCEPTION 'Group not found'; END IF; DELETE FROM bot_group_members WHERE group_id=g.id; END IF; INSERT INTO bot_group_members(group_id,bot_id,position) SELECT g.id,x,ord::integer-1 FROM unnest(p_members) WITH ORDINALITY AS t(x,ord); RETURN g; END $$;
REVOKE ALL ON FUNCTION public.save_bot_group(text,uuid,uuid[],text,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_bot_group(text,uuid,uuid[],text,uuid) TO authenticated;
CREATE TABLE public.agent_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, conversation_id uuid NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE, bot_id uuid REFERENCES public.bots(id) ON DELETE SET NULL, goal text NOT NULL CHECK(length(goal) BETWEEN 1 AND 4000), system_prompt text NOT NULL, event_id text, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','completed','failed','cancelled')), result text, error text, cursor_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.agent_jobs TO authenticated; GRANT ALL ON public.agent_jobs TO service_role;
ALTER TABLE public.agent_jobs ENABLE ROW LEVEL SECURITY; CREATE POLICY "jobs own read" ON public.agent_jobs FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TRIGGER agent_jobs_updated BEFORE UPDATE ON public.agent_jobs FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TABLE public.agent_action_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, conversation_id uuid NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE, account_id text NOT NULL, tool_slug text NOT NULL, arguments jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','running','completed','rejected','failed')), result jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.agent_action_requests TO authenticated; GRANT ALL ON public.agent_action_requests TO service_role;
ALTER TABLE public.agent_action_requests ENABLE ROW LEVEL SECURITY; CREATE POLICY "actions own read" ON public.agent_action_requests FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TRIGGER agent_action_updated BEFORE UPDATE ON public.agent_action_requests FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();